  test("deferred claims scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "3.00");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
    await ui.setSetting(pg_uma, "terms-C", "20");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "0.40"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-02-25"}));
    const c_cam_1 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "25.00"}, p_cam));
    expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
    expect(await ui.addPatron(pg_uma, p_cam, "Ada")).toBe(true);
    expect(await ui.editClaim(pg_uma, c_ben_0, {"date": "2026-03-01"})).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.defer(pg_uma, c_cam_1, "2026-04-01")).toBe(true);
    expect(await ui.addPatron(pg_uma, p_cam, "Ada")).toBe(false);
    expect(await ui.pasteClaims(pg_uma, "Ada,20.00,2026-03-28,paste\nCam,0.04,,\nBen,3.33,2026-03-28,")).toBe(3);
    const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
    const c_cam_2 = await ui.claimAt(pg_uma, p_cam, 2);
    const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
    const c_cam_3 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00"}));
    await ui.setSetting(pg_uma, "clerk-limit", "");
    const c_cam_4 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.04", "date": "2026-03-20"}));
    const c_cam_5 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-03-09"}));
    await ui.refresh(pg_uma);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    const c_ben_2 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35", "date": "2026-04-02"}));
    expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nBen,A,,0.00\nCam,C,,n/a\nAda,A,,0.00\n");
    const c_cam_6 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-03-01"}));
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_cam_1, "settle")).toBe(false);
    expect(await ui.setRate(pg_vic, {"grade": "B", "pct": "12.50"})).toBe(true);
    await ui.refresh(pg_vic);
    await ui.expectAudit(sheet, [
    ]);
  });
  test("deferred claims scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "1.50");
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "terms-C", "3");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    expect(await ui.setSettingDated(pg_uma, "clerk-limit", "3.00", "2026-03-15", "1.50")).toBe(true);
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.04"}));
    expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35", "date": "2026-03-20"}));
    expect(await ui.editPerson(pg_uma, p_ben, {"grade": "A"})).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    await ui.setToday(pg_uma, "2026-03-31");
    await ui.refresh(pg_uma);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    const c_cam_1 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "1.00"}));
    expect(await ui.statement(pg_vic, p_cam)).toBe(true);
    expect(await ui.claimAction(pg_vic, c_cam_1, "open")).toBe(true);
    await ui.setToday(pg_vic, "2026-05-07");
    const c_ada_1 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "1.00", "date": "2026-03-01"}));
    const c_cam_2 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "99.95", "date": "2026-03-01"}));
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_cam_2, "open")).toBe(true);
    expect(await ui.hold(pg_vic, p_cam, {"from": "2026-03-05"})).toBe(true);
    expect(await ui.retire(pg_vic, p_ben, "2026-03-05")).toBe(true);
    expect(await ui.statement(pg_vic, p_ada)).toBe(true);
    expect(await ui.statement(pg_vic, p_cam)).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.claimAction(pg_uma, c_ada_1, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ben)).toHaveCount(0);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ben)).toHaveCount(0);
    await ui.expectAudit(sheet, [
    ]);
  });
});

