/**
 * Opens each selected claim that can be opened, in list order (people in the order they were added, a person's
 * claims newest first): as the single open does, it must be a DRAFT not dated inside a closed period, takes its
 * number (see ClaimNumbering) and records who opened it, adds its OPEN line to its status log (see ClaimLog), then writes CLAIM_OPENED and the figures it moved (see Rollup).
 * Each that cannot, or is not on the sheet, is left as it is and counted refused.
 */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, SettingRepository settings, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
            Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.claimIds());
        List<Person> listed = people.list(sheet);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).id(), i);
        }
        Map<Long, Person> byId = listed.stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
                .toList();
        int opened = 0;
        for (Claim claim : chosen) {
            if (claim.status() != ClaimStatus.DRAFT || periods.closedOn(sheet, claim.date())) {
                continue;
            }
            RollupBefore before = rollup.take(sheet);
            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
            Claim toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), ClaimStatus.OPEN, number, claim.due(), request.by(), claim.stated(),
                    claim.statedDue(), claim.corrects(), claim.dueBy());
            if (!claims.updateStatus(toSave, ClaimStatus.DRAFT)) {
                continue;
            }
            opened++;
            log.write(toSave, request.by());
            Person person = byId.get(claim.personId());
            audit.record("CLAIM_OPENED sheet=" + sheet + " by=" + request.by() + " person="
                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                    + " date=" + claim.date() + " number=" + number);
            rollup.record(sheet, request.by(), before);
        }
        result.set(new BulkOpenResult(opened, selected.size() - opened));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.Function;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The late charge on a sheet as of its today: an overdue claim (OPEN or PENDING, its due-by — fixed when it was added — before
 * today) gains the late percent in force on its date of its figure for every full 30 days it is overdue, rounded to two
 * decimals by the claim's rounding (see Rounding). The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
 */
public record LateCharge(LocalDate today, Function<LocalDate, BigDecimal> pct, Rounding rounding) {

    /** The days in each step of the charge. */
    public static final int DAYS = 30;

    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings,
            ClaimRepository claims) {
        return new LateCharge(sheets.today(sheetId), (date) -> settings.latePct(sheetId, date),
                Rounding.of(sheetId, sheets, settings, claims));
    }

    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, or
     *  is a correction. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.dueBy(), today);
        long steps = overdue <= 0 ? 0 : overdue / DAYS;
        return figure.multiply(pct.apply(claim.date())).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
                .setScale(2, rounding.mode(claim));
    }

    /** The figure with its charge added on top; null when it has none. */
    public BigDecimal add(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.add(on(claim, figure));
    }
}
